// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX, Log} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function testFuzz_property(uint256 initialMinSum, uint256 newMinSum, address actor) public {
        vm.assume(actor != address(0));
        // initialize the contract: after this, SetMinSum must have no effect
        c.SetMinSum(initialMinSum);
        c.SetLogFile(address(new Log()));
        c.Initialized();

        vm.prank(actor);
        try c.SetMinSum(newMinSum) {
            // reverts in reference; nothing to do here
        } catch {
            // expected on the reference
        }

        // General rule: after initialization, MinSum always equals the value
        // set before initialization, no matter who calls SetMinSum or with what value.
        assertTrue(c.MinSum() == initialMinSum, "MinSum changed after initialization");
    }
}
